// spec: specs/nav-menu-a11y.md (1.1) · кейсы: .qa/tests/nav-menu-a11y/NAV-A11Y-01.md, NAV-A11Y-02.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен.
// Источник: #2f6eef «מה רצוי» «לכפתור יהיה שם נגיש, למשל aria-label="תפריט"»; комментарий программиста PR #198 —
// иконка скрыта от скринридера. Кнопку ищем ТОЛЬКО с exact: true — у кнопки доступности имя «פתח תפריט נגישות».
// После открытия Radix Sheet прячет фон (aria-hidden) — состояние кнопки читаем с includeHidden.
import { test, expect } from '@playwright/test';
import { PageKey, pathOf, prepareReadOnly, dismissPopups, waitReady, LOAD } from '../html-rtl-dir/rtl-dir.helpers';

test.use({ serviceWorkers: 'block' });

const NAME = 'תפריט';
// /guides не проверяется гостем: с #359741 гость уходит на главную — тест проверил бы главную (ложно-зелёный).
const PAGES: PageKey[] = ['home', 'search', 'category', 'listing', 'calculator'];

test.describe('Кнопка мобильного меню — доступное имя «תפריט»', () => {
  for (const key of PAGES) {
    test(`${key}: кнопка ☰ в шапке называется «${NAME}», иконка aria-hidden, меню открывается #2f6eef @mobile @prod-safe`, async ({ page, context, request }) => {
      const path = await pathOf(request, key);
      await prepareReadOnly(context);
      await dismissPopups(page);
      await page.goto(path);
      await waitReady(page, key);

      const button = page.getByRole('banner').getByRole('button', { name: NAME, exact: true });
      await expect(button, `${path}: одна кнопка «${NAME}» в шапке`).toHaveCount(1);
      await expect(button).toBeVisible();
      await expect(button, 'доступное имя').toHaveAccessibleName(NAME);
      const icons = button.locator('svg');
      await expect(icons, 'иконка ☰ на месте').not.toHaveCount(0);
      for (const icon of await icons.all()) await expect(icon, 'иконка скрыта от скринридера').toHaveAttribute('aria-hidden', 'true');
      await expect(button, 'меню закрыто').toHaveAttribute('aria-expanded', 'false');
      await expect(page.getByRole('button', { name: 'פתח תפריט נגישות', exact: true }), 'кнопка נגישות на месте, имя не изменилось').toBeVisible();

      await button.click();
      const menu = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: NAME, exact: true }) });
      await expect(menu, 'открыто меню «תפריט»').toBeVisible(LOAD);
      const trigger = page
        .getByRole('banner', { includeHidden: true })
        .getByRole('button', { name: NAME, exact: true, includeHidden: true });
      await expect(trigger, 'aria-expanded после открытия').toHaveAttribute('aria-expanded', 'true');
    });
  }
});
